import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseInt("9223372036854775808")
    match a {
        Some(v) => { io.println("edge-bad ${v}") }
        None => { io.println("edge-none") }
    }
    let b = string.parseInt("99999999999999999999")
    match b {
        Some(v) => { io.println("far-bad ${v}") }
        None => { io.println("far-none") }
    }
    return Ok(())
}
